'use strict';
const groupSvg=path=>`<svg class="group-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${path}"/></svg>`;
const GROUPS={chest:[groupSvg('M5 13c0-5 2-8 5-8 1 0 2 1 2 3 0-2 1-3 2-3 3 0 5 3 5 8 0 4-3 6-7 6s-7-2-7-6Z'),'Грудь'],back:[groupSvg('M8 4c1 2 2 3 4 3s3-1 4-3l2 5-2 11H8L6 9l2-5Z'),'Спина'],shoulders:[groupSvg('M4 14c1-5 4-8 8-8s7 3 8 8M7 18h10'),'Плечи'],biceps:[groupSvg('M7 15c1-5 3-7 6-6l1-4 3 2-2 4c3 3 1 8-4 8H7v-4Z'),'Бицепс'],triceps:[groupSvg('M8 6h5l3 4-2 9H8l-2-7 2-6Z'),'Трицепс'],legs:[groupSvg('M9 4h6l-1 7 3 9h-4l-2-6-1 6H6l3-9V4Z'),'Ноги'],glutes:[groupSvg('M6 13c0-5 2-8 6-8s6 3 6 8-2 7-6 7-6-2-6-7Zm6-8v15'),'Ягодицы'],abs:[groupSvg('M8 4h8l2 16H6L8 4Zm4 0v16M7 9h10M7 15h10'),'Пресс']};
const WEEKDAYS=['Понедельник','Вторник','Среда','Четверг','Пятница','Суббота','Воскресенье'];
const DEFAULT_WEEKDAYS=[0,2,4,1,3,5,6];
const KEY='ritm-gym-prototype-v1',uid=()=>crypto.randomUUID();
const ex=(name,group,sets=3,reps=12,weight='')=>({id:uid(),name,group,sets,reps,weight,note:''});
const initial=()=>({version:1,selected:null,done:{},days:[],sessions:[]});
let state=initial(),confirmed=initial(),storageError=false;
let editing=null,showForm=false,dirty=false;
let linkedDay=new URLSearchParams(location.search).get('day');
const app=document.querySelector('#app');
app.innerHTML='<div class="app-skeleton" role="status" aria-label="Загружаем программу"><span class="app-skeleton-line short"></span><span class="app-skeleton-card"></span><span class="app-skeleton-card"></span></div>';
const migration=document.createElement('section');migration.className='gym-migration';migration.dataset.gymMigration='';migration.hidden=true;migration.innerHTML='<h3>Записи этого браузера</h3><p class="helper">Перенос и локальная копия доступны здесь, не под шапкой приложения.</p>';document.querySelector('#gym-settings [data-device-notifications]').before(migration);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const program=()=>location.pathname.replace(/\/$/,'').endsWith('/program'),current=()=>state.days.find(d=>d.id===linkedDay)||state.days.find(d=>d.id===state.selected)||state.days[0];
const gymStore=new HubStore('gym',KEY,(next)=>{state=next;confirmed=structuredClone(next);render()},()=>dirty||showForm||!!document.querySelector('dialog[open]'));
async function save(){const next=structuredClone(state);state=structuredClone(confirmed);const result=await gymStore.save({state:next});if(!result){state=structuredClone(confirmed);notify('Изменение не подтверждено сервером.');return false}return true}
function notify(message){const n=document.querySelector('#notice');n.textContent=message;n.style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>n.style.display='none',3500);}
const badge=g=>GROUPS[g]?`<span class="badge">${GROUPS[g][0]} ${GROUPS[g][1]}</span>`:'';
const nextDayName=()=>`День ${Math.max(0,...state.days.map(day=>Number(/^День (\d+)$/.exec(day.name)?.[1]||0)))+1}`;
const info=e=>`${e.sets} × ${e.reps}${e.weight!==''?` · ${esc(e.weight)} кг`:''}`;
async function selectDay(id){linkedDay=null;state.selected=id;editing=null;showForm=false;if(!await save())return;render();}
async function setDone(ids,completed){const d=current();if(!d||ids.some(id=>!d.exercises.some(e=>e.id===id)))throw Error('Упражнение не найдено');for(const id of ids){if(completed)state.done[id]=true;else delete state.done[id];}if(!await save())return;render();return {completed:d.exercises.filter(e=>state.done[e.id]).length,total:d.exercises.length};}
function navigate(path){document.querySelector('dialog:not([data-app-settings])')?.close();history.pushState({},'',path);editing=null;showForm=false;dirty=false;render();window.scrollTo(0,0);}
function render(){const c=Catalog.active(),h=GymHistory.visible();app.classList.toggle('catalog-page',c);app.classList.toggle('history-page',h);const d=current(),p=program(),done=d?d.exercises.filter(e=>state.done[e.id]).length:0;document.title=`${h?'История':c?'Упражнения':p?'Программа':'Тренировка'} — Ритм`;document.querySelectorAll('nav a').forEach(a=>{a.removeAttribute('aria-current');if(a.getAttribute('href')===(h?'/gym/#history':c?'/gym/catalog':p?'/gym/program':'/gym'))a.setAttribute('aria-current','page');});if(c){Catalog.render();return;}if(h){app.innerHTML=GymHistory.historyView();dirty=false;return;}if(!p&&GymHistory.active()){app.innerHTML=GymHistory.activeView();dirty=false;GymHistory.updateTimer();return;}
app.innerHTML=`<div class="heading"><div><p class="eyebrow">${p?'СОБЕРИ СВОЙ ПЛАН':'ТВОЙ ТЕМП. ТВОЯ ПРОГРАММА.'}</p><h1>${p?'Программа':'Тренировка'}</h1><p>${p?'Дни, группы мышц и упражнения.':'Выбери день и двигайся по списку.'}</p></div>${p?'<button data-action="add-day">＋ День</button>':''}</div>${state.days.length?`<div class="days" aria-label="Дни программы">${[...state.days].sort((a,b)=>(a.weekday??7)-(b.weekday??7)).map(day=>`<button class="day ${day.id===d.id?'active':''}" data-day="${day.id}" aria-pressed="${day.id===d.id}"><small>${WEEKDAYS[day.weekday]||'Без привязки'}</small><strong>${esc(day.name)}</strong><span class="icons">${day.groups.map(badge).join('')}</span></button>`).join('')}</div>`:''}
${!d?`<section class="panel empty"><h2>Твоя программа начинается здесь</h2><p>Добавь первый день и упражнения для него.</p><br>${p?'<button data-action="add-day">Создать день</button>':'<button data-action="add-day">Составить программу</button>'}</section>`:p?programView(d):`<section class="panel"><div class="panel-head"><div><h2>${esc(d.name)}</h2><p>${done===d.exercises.length&&done>0?'<span class="success">Всё выполнено. Отличная работа!</span>':'Отмечай упражнение после всех подходов.'}</p></div>${d.exercises.length?'<button data-session-start>Начать тренировку</button>':''}<div class="count">${done}<small> / ${d.exercises.length}</small></div></div><div class="progress" role="progressbar" aria-label="Выполнено упражнений" aria-valuemin="0" aria-valuemax="${d.exercises.length||1}" aria-valuenow="${done}"><span style="width:${d.exercises.length?done/d.exercises.length*100:0}%"></span></div>${d.exercises.length?d.exercises.map((e,i)=>`<div class="exercise ${state.done[e.id]?'done':''}"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h3><label for="done-${e.id}">${esc(e.name)}</label></h3><p>${info(e)} · ${GROUPS[e.group]?.[0]||''} ${GROUPS[e.group]?.[1]||''}</p>${e.note?`<p class="note">${esc(e.note)}</p>`:''}${e.reference?`<button class="secondary exercise-info" data-exercise-info="${e.id}">Техника выполнения</button>`:''}</div><input id="done-${e.id}" type="checkbox" data-done="${e.id}" ${state.done[e.id]?'checked':''} aria-label="${esc(e.name)} выполнено"></div>`).join(''):'<div class="empty"><p>В этом дне пока нет упражнений.</p><br><button data-action="add-exercise">Добавить упражнения</button></div>'}</section><div class="footer"><p class="helper">Отметки сохраняются, даже если закрыть страницу.</p><button class="secondary" data-action="reset" ${done?'':'disabled'}>Начать заново</button></div>`}<p class="helper" style="margin-top:28px">${storageError?'⚠ Сохранение недоступно или данные повреждены.':'Программа и отметки сохраняются на сервере.'}</p>`;dirty=false;}
function programView(d){return `<section class="panel"><div class="panel-head"><div><h2>${esc(d.name)}</h2><p>${d.exercises.length} упр. в этом дне</p></div><button class="secondary" data-action="edit-day">Изменить день</button></div>${d.exercises.length?d.exercises.map((e,i)=>`<div class="edit-row"><div><h3>${esc(e.name)}</h3><p>${badge(e.group)} &nbsp; ${info(e)}</p>${e.note?`<p class="note">${esc(e.note)}</p>`:''}</div>${e.reference?`<button class="secondary exercise-info" data-exercise-info="${e.id}">Техника выполнения</button>`:''}<div class="toolbar"><button class="icon-button" data-up="${e.id}" aria-label="Поднять ${esc(e.name)}" ${i===0?'disabled':''}>↑</button><button class="icon-button" data-down="${e.id}" aria-label="Опустить ${esc(e.name)}" ${i===d.exercises.length-1?'disabled':''}>↓</button><button class="secondary" data-edit="${e.id}" aria-label="Изменить ${esc(e.name)}">Изменить</button><button class="icon-button danger" data-remove="${e.id}" aria-label="Удалить ${esc(e.name)}">×</button></div></div>`).join(''):'<div class="empty"><p>Добавь первое упражнение этого дня.</p></div>'}${showForm?exerciseForm(d):'<div class="toolbar program-add"><button data-action="add-exercise">＋ Своё упражнение</button><a class="secondary button" href="/gym/catalog">Из каталога</a></div>'}</section><div class="footer"><p class="helper">Подходы, повторения и вес настраиваются в упражнении.</p><a href="/gym" class="secondary button">К тренировке →</a></div>`;}
function exerciseForm(d){const e=d.exercises.find(e=>e.id===editing);return `<form id="exercise-form" class="editor"><h2>${e?'Изменить упражнение':'Новое упражнение'}</h2><div class="form-grid"><label class="field full">Название<input name="name" required maxlength="100" placeholder="Например, жим лёжа" value="${esc(e?.name||'')}"></label><label class="field full">Группа мышц<select name="group">${Object.entries(GROUPS).map(([key,[icon,name]])=>`<option value="${key}" ${key===(e?.group||d.groups[0])?'selected':''}>${name}</option>`).join('')}</select></label><label class="field">Подходы<input name="sets" type="number" min="1" max="50" step="1" required value="${e?.sets||3}"></label><label class="field">Повторения<input name="reps" type="number" min="1" max="1000" step="1" required value="${e?.reps||12}"></label><label class="field full">Вес, кг · необязательно<input name="weight" type="number" min="0" max="2000" step="0.25" placeholder="Без веса" value="${esc(e?.weight??'')}"></label><label class="field full">Заметка · необязательно<textarea name="note" rows="2" maxlength="500" placeholder="Техника, настройки тренажёра…">${esc(e?.note||'')}</textarea></label></div><div class="toolbar"><button type="submit">Сохранить упражнение</button><button type="button" class="secondary" data-action="cancel-exercise">Отмена</button></div></form>`;}
function modal(content){document.querySelector('dialog:not([data-app-settings])')?.remove();const dlg=document.createElement('dialog');dlg.innerHTML=content;document.body.append(dlg);dlg.showModal();requestAnimationFrame(()=>{const title=dlg.querySelector('h2');if(title){title.tabIndex=-1;title.focus({preventScroll:true})}});dlg.addEventListener('close',()=>dlg.remove());return dlg;}
function confirmAction(title,description,button,action){const dlg=modal(`<h2>${esc(title)}</h2><p>${esc(description)}</p><div class="toolbar" style="margin-top:24px"><button id="confirm">${esc(button)}</button><button class="secondary" id="cancel">Отмена</button></div>`);dlg.querySelector('#cancel').onclick=()=>dlg.close();dlg.querySelector('#confirm').onclick=()=>{dlg.close();action();};}
function withDiscard(action){if(dirty)confirmAction('Не сохранять изменения?','Поля упражнения изменены. При переходе эти изменения потеряются.','Не сохранять',()=>{dirty=false;action();});else action();}
function deleteDay(d=current()){if(!d)return;confirmAction('Удалить день?',`«${d.name}» и все его упражнения будут удалены.`,'Удалить',async()=>{for(const e of d.exercises)delete state.done[e.id];state.days=state.days.filter(day=>day.id!==d.id);state.selected=state.days[0]?.id||null;if(!await save())return;render();notify('День удалён')})}
function editDay(create,onSaved){const d=create?null:current(),weekday=d?.weekday??null,name=d?.name||nextDayName();const dlg=modal(`<form id="day-form" class="day-form"><h2>${create?'Новый день':'Настройки дня'}</h2><p class="day-name-preview">${esc(name)}</p><label class="field">День недели<select name="weekday"><option value="" ${weekday===null?'selected':''}>Без привязки к неделе</option>${WEEKDAYS.map((label,i)=>`<option value="${i}" ${i===weekday?'selected':''}>${label}</option>`).join('')}</select></label><fieldset><legend>Группы мышц · необязательно</legend><div class="group-options">${Object.entries(GROUPS).map(([key,[icon,label]])=>`<label class="group-choice"><input type="checkbox" name="groups" value="${key}" ${d?.groups.includes(key)?'checked':''}>${icon}<span>${label}</span></label>`).join('')}</div></fieldset><p id="group-error" role="alert" class="day-error"></p><div class="toolbar"><button type="submit">Сохранить день</button><button class="secondary" type="button" id="close-day">Отмена</button></div></form>`);dlg.querySelector('#close-day').onclick=()=>dlg.close();dlg.querySelector('#day-form').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.currentTarget),selectedWeekday=f.get('weekday')===''?null:Number(f.get('weekday'));if(selectedWeekday!==null&&(!Number.isInteger(selectedWeekday)||selectedWeekday<0||selectedWeekday>6))return;const groups=f.getAll('groups');if(d){const target=state.days.find(x=>x.id===d.id);if(!target){notify('День удалён на другом устройстве.');return}target.groups=groups;target.weekday=selectedWeekday}else{const day={id:uid(),name,groups,weekday:selectedWeekday,exercises:[]};state.days.push(day);state.selected=day.id}if(!await save())return;dlg.close();render();notify('День сохранён');onSaved?.()}}
function polishExerciseActions(){
 const add=app.querySelector('[data-action="add-exercise"]');
 if(add&&!program()){const choice=document.createElement('div');choice.className='exercise-choice';choice.innerHTML='<a class="button" href="/gym/catalog">Выбрать из каталога</a><button class="secondary" data-action="custom-exercise">Добавить своё</button>';add.replaceWith(choice)}
 const toolbar=app.querySelector('.program-add');if(toolbar){const own=toolbar.querySelector('[data-action="add-exercise"]'),catalog=toolbar.querySelector('a[href="/gym/catalog"]');if(own){own.dataset.action='custom-exercise';own.textContent='Добавить своё'}if(catalog){catalog.classList.remove('secondary');catalog.classList.add('button');if(toolbar.firstElementChild!==catalog)toolbar.prepend(catalog)}}
 if(program()&&current()){const head=app.querySelector('.panel>.panel-head');if(head&&!head.querySelector('[data-action="delete-day"]')){const remove=document.createElement('button');remove.className='danger';remove.dataset.action='delete-day';remove.textContent='Удалить день';head.append(remove)}}
}
new MutationObserver(polishExerciseActions).observe(app,{childList:true,subtree:true});
document.addEventListener('click',event=>{const button=event.target.closest('button');if(button?.dataset.action==='custom-exercise'){withDiscard(()=>{if(!current())return;if(!program())navigate('/gym/program');showForm=true;editing=null;render()})}if(button?.dataset.action==='delete-day')withDiscard(()=>deleteDay())});
document.addEventListener('click',event=>{const link=event.target.closest('a');if(link&&link.origin===location.origin&&['/gym','/gym/program','/gym/catalog'].includes(link.pathname.replace(/\/$/,''))&&!event.ctrlKey&&!event.metaKey){event.preventDefault();withDiscard(()=>navigate(link.pathname+link.hash));return;}const b=event.target.closest('button');if(!b||b.disabled)return;const d=current();if(b.dataset.day){withDiscard(()=>selectDay(b.dataset.day));return;}if(b.dataset.edit){withDiscard(()=>{editing=b.dataset.edit;showForm=true;render();document.querySelector('#exercise-form input').focus();});return;}if(b.dataset.remove){withDiscard(()=>confirmAction('Удалить упражнение?',d.exercises.find(e=>e.id===b.dataset.remove).name,'Удалить',async ()=>{d.exercises=d.exercises.filter(e=>e.id!==b.dataset.remove);delete state.done[b.dataset.remove];if(!await save())return;render();}));return;}if(b.dataset.up||b.dataset.down){withDiscard(async ()=>{const id=b.dataset.up||b.dataset.down,i=d.exercises.findIndex(e=>e.id===id),target=i+(b.dataset.up?-1:1);if(target>=0&&target<d.exercises.length){[d.exercises[i],d.exercises[target]]=[d.exercises[target],d.exercises[i]];if(!await save())return;render();}});return;}switch(b.dataset.action){case'add-day':withDiscard(()=>editDay(true));break;case'edit-day':withDiscard(()=>editDay(false));break;case'add-exercise':withDiscard(()=>{if(!current())return;if(!program())navigate('/gym/program');showForm=true;editing=null;render();document.querySelector('#exercise-form input').focus();});break;case'cancel-exercise':withDiscard(()=>{editing=null;showForm=false;render();});break;case'reset':confirmAction('Начать тренировку заново?','Сбросятся только отметки выбранного дня. Упражнения останутся.','Сбросить отметки',()=>setDone(d.exercises.map(e=>e.id),false));break;}});
// Preserve whole-row completion while keeping the technique button independent.
document.addEventListener('click',event=>{const row=event.target.closest('.exercise');if(row&&!event.target.closest('button,a,input,label'))row.querySelector('input[data-done]')?.click();});
document.addEventListener('change',e=>{if(e.target.dataset.done)setDone([e.target.dataset.done],e.target.checked);});
document.addEventListener('input',e=>{if(e.target.closest('#exercise-form')){dirty=true;e.target.setCustomValidity?.('');}});
document.addEventListener('submit',async event=>{if(event.target.id!=='exercise-form')return;event.preventDefault();const form=event.target,f=new FormData(form),name=f.get('name').trim();if(!name){form.elements.name.setCustomValidity('Введи название упражнения');form.elements.name.reportValidity();return;}const d=current(),previous=d.exercises.find(e=>e.id===editing),updated={...previous,id:editing||uid(),name,group:f.get('group'),sets:Number(f.get('sets')),reps:Number(f.get('reps')),weight:f.get('weight')===''?'':Number(f.get('weight')),note:f.get('note').trim()};if(editing){const i=d.exercises.findIndex(e=>e.id===editing);d.exercises[i]=updated;}else d.exercises.push(updated);if(!d.groups.includes(updated.group))d.groups.push(updated.group);if(!await save())return;editing=null;showForm=false;dirty=false;render();notify('Упражнение сохранено');});
window.addEventListener('popstate',()=>{document.querySelector('dialog:not([data-app-settings])')?.close();dirty=false;editing=null;showForm=false;render();});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
gymStore.load();
window.addEventListener('hub-save-recovered',event=>{if(event.detail==='gym'){editing=null;showForm=false;dirty=false;render()}});
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tools=[{name:'read_training_program',description:'Read the days, exercises and completion state.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>JSON.parse(JSON.stringify(state))},{name:'set_exercises_completed',description:'Set completion for exercises of the selected day and update the tracker.',inputSchema:{type:'object',properties:{exerciseIds:{type:'array',items:{type:'string'},minItems:1},completed:{type:'boolean'}},required:['exerciseIds','completed'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!Array.isArray(input.exerciseIds)||!input.exerciseIds.length||input.exerciseIds.some(x=>typeof x!=='string')||typeof input.completed!=='boolean')throw Error('Invalid input');if(dirty)throw Error('Save the draft first');return setDone(input.exerciseIds,input.completed);}}];for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}

window.resetAppRecords=async()=>{
 if(!await gymStore.save({command:'reset'}))return false;
 editing=null;showForm=false;dirty=false;
 document.querySelectorAll('dialog:not([data-app-settings])').forEach(dialog=>dialog.remove());
 render();notify('Программа и история тренировок сброшены');return true;
};
